import { getPersons } from "../components/apiutils";
import Nav from "../components/Nav";
import {useState,useEffect} from "react";
import { Link, Outlet } from "react-router-dom";
import './userMgmt.css';


export default function UserMgmt(){
    const [users, setUsers] = useState([]);
    useEffect(()=>{
        getPersons()
        .then((users)=>{
            setUsers(users)
        })
    },[]);

    return <>
    <Nav>
        <div>
            <Link to="/users/add"><button>Add User</button></Link>
        </div>
        
        <table>
            <thead>
                <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Phone</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                {users.map((user)=>{
                    return <tr key={user.id}>
                        <td>{user.name}</td>
                        <td>{user.email}</td>
                        <td>{user.mobile}</td> 
                        <td>
                            <Link to={`users/${user.id}`}>View Details</Link>
                        </td>
                    </tr>
                })}
            </tbody>
        </table>
        <Outlet/>  {/*place holder of child component or where child component will be rendered   this helps in minimum intereaction with server  */}
    </Nav>
    </>
}
